#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE 1000

typedef struct Post {
    int id;
    int parent_id;
    char message[MAX_LINE];
    int depth;
    struct Post **children;
    int child_count;
    int child_capacity;
} Post;

Post* create_post(int id, int parent_id, const char *message) {
    Post *p = (Post*)malloc(sizeof(Post));
    p->id = id;
    p->parent_id = parent_id;
    strcpy(p->message, message);
    p->depth = 0;
    p->children = NULL;
    p->child_count = 0;
    p->child_capacity = 0;
    return p;
}

void add_child(Post *parent, Post *child) {
    if (parent->child_count == parent->child_capacity) {
        parent->child_capacity = parent->child_capacity == 0 ? 2 : parent->child_capacity * 2;
        parent->children = (Post**)realloc(parent->children, parent->child_capacity * sizeof(Post*));
    }
    parent->children[parent->child_count++] = child;
}

void set_depths(Post *post, int depth) {
    post->depth = depth;
    for (int i = 0; i < post->child_count; i++) {
        set_depths(post->children[i], depth + 1);
    }
}

int compare_posts(const void *a, const void *b) {
    Post *pa = *(Post**)a;
    Post *pb = *(Post**)b;
    return pa->id - pb->id;
}

void print_post(Post *post) {
    for (int i = 0; i < post->depth; i++) {
        putchar('.');
    }
    printf("%s\n", post->message);
    qsort(post->children, post->child_count, sizeof(Post*), compare_posts);
    for (int i = 0; i < post->child_count; i++) {
        print_post(post->children[i]);
    }
}

int main() {
    int n;
    scanf("%d", &n);

    Post **posts = (Post**)malloc(n * sizeof(Post*));
    Post *root = NULL;

    for (int i = 0; i < n; i++) {
        int id, parent;
        char msg[MAX_LINE];
        scanf("%d %d", &id, &parent);
        fgets(msg, MAX_LINE, stdin);
        // Remove trailing newline
        int len = strlen(msg);
        if (len > 0 && msg[len-1] == '\n') {
            msg[len-1] = '\0';
        }
        // Remove leading space if any
        if (msg[0] == ' ') {
            memmove(msg, msg+1, strlen(msg));
        }

        posts[i] = create_post(id, parent, msg);
        if (parent == 0) {
            root = posts[i];
        }
    }

    // Build tree structure
    for (int i = 0; i < n; i++) {
        if (posts[i]->parent_id != 0) {
            for (int j = 0; j < n; j++) {
                if (posts[j]->id == posts[i]->parent_id) {
                    add_child(posts[j], posts[i]);
                    break;
                }
            }
        }
    }

    // Set depths starting from root
    if (root) {
        set_depths(root, 0);
        print_post(root);
    }

    // Free memory
    for (int i = 0; i < n; i++) {
        free(posts[i]->children);
        free(posts[i]);
    }
    free(posts);

    return 0;
}

