#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 1005
#define MAXMSG 1005

typedef struct ChildNode {
    int id;
    struct ChildNode *next;
} ChildNode;

static ChildNode *children[MAXN];
static char msg[MAXN][MAXMSG];
static int exists_post[MAXN];

void add_child(int parent, int child) {
    ChildNode *node = (ChildNode *)malloc(sizeof(ChildNode));
    node->id = child;
    node->next = NULL;

    if (children[parent] == NULL || children[parent]->id > child) {
        node->next = children[parent];
        children[parent] = node;
        return;
    }

    ChildNode *cur = children[parent];
    while (cur->next != NULL && cur->next->id < child) cur = cur->next;
    node->next = cur->next;
    cur->next = node;
}

void print_thread(int u, int depth) {
    for (int i = 0; i < depth; i++) putchar('.');
    printf("%s\n", msg[u]);

    ChildNode *cur = children[u];
    while (cur != NULL) {
        print_thread(cur->id, depth + 1);
        cur = cur->next;
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    getchar(); /* consume newline after n */

    for (int i = 0; i < n; i++) {
        int id, parent;
        if (scanf("%d %d", &id, &parent) != 2) return 0;
        getchar(); /* consume single space/newline before message */

        if (!fgets(msg[id], sizeof(msg[id]), stdin)) return 0;
        size_t len = strlen(msg[id]);
        if (len > 0 && msg[id][len - 1] == '\n') msg[id][len - 1] = '\0';

        exists_post[id] = 1;
        add_child(parent, id);
    }

    ChildNode *cur = children[0];
    while (cur != NULL) {
        print_thread(cur->id, 0);
        cur = cur->next;
    }

    return 0;
}

