public class Main {
    static class Node {
        int id;
        int parent;
        String msg;
        List<Integer> children = new ArrayList<>();

        Node(int id, int parent, String msg) {
            this.id = id;
            this.parent = parent;
            this.msg = msg;
        }
    }

    static Map<Integer, Node> map = new HashMap<>();
    static List<Integer> roots = new ArrayList<>();
    static StringBuilder out = new StringBuilder();

    static void dfs(int id, int depth) {
        Node cur = map.get(id);
        for (int i = 0; i < depth; i++) out.append('.');
        out.append(cur.msg).append('\n');
        for (int child : cur.children) {
            dfs(child, depth + 1);
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first;
        while ((first = br.readLine()) != null && first.trim().isEmpty()) {
            // skip leading empty lines
        }
        if (first == null) return;

        int n = Integer.parseInt(first.trim());

        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            while (line != null && line.isEmpty()) line = br.readLine();
            if (line == null) break;

            int p = 0;
            while (p < line.length() && Character.isWhitespace(line.charAt(p))) p++;

            int sign = 1;
            if (line.charAt(p) == '-') {
                sign = -1;
                p++;
            }
            int id = 0;
            while (p < line.length() && Character.isDigit(line.charAt(p))) {
                id = id * 10 + (line.charAt(p) - '0');
                p++;
            }
            id *= sign;

            while (p < line.length() && Character.isWhitespace(line.charAt(p))) p++;

            sign = 1;
            if (line.charAt(p) == '-') {
                sign = -1;
                p++;
            }
            int parent = 0;
            while (p < line.length() && Character.isDigit(line.charAt(p))) {
                parent = parent * 10 + (line.charAt(p) - '0');
                p++;
            }
            parent *= sign;

            while (p < line.length() && Character.isWhitespace(line.charAt(p))) p++;
            String msg = (p < line.length()) ? line.substring(p) : "";

            map.put(id, new Node(id, parent, msg));
        }

        for (Node node : map.values()) {
            if (node.parent == 0 || !map.containsKey(node.parent)) {
                roots.add(node.id);
            } else {
                map.get(node.parent).children.add(node.id);
            }
        }

        Collections.sort(roots);
        for (Node node : map.values()) {
            Collections.sort(node.children);
        }

        for (int root : roots) {
            dfs(root, 0);
        }

        System.out.print(out.toString());
    }
}

