struct Post {
    int id;
    string message;
    vector<int> children;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Post> posts(n);
    vector<int> parent(n, -1);

    // Read posts
    for (int i = 0; i < n; i++) {
        int id, parent_id;
        string msg;
        cin >> id >> parent_id;
        cin.ignore(); // ignore space before message
        getline(cin, msg);

        posts[i].id = id;
        posts[i].message = msg;

        if (parent_id != 0) {
            parent[i] = parent_id;
        }
    }

    // Build tree structure
    // First, find root (post with id = 1)
    int root_idx = -1;
    for (int i = 0; i < n; i++) {
        if (posts[i].id == 1) {
            root_idx = i;
            break;
        }
    }

    // Build adjacency list using IDs
    vector<vector<int>> children_by_id(n + 1); // 1-indexed IDs
    for (int i = 0; i < n; i++) {
        int pid = parent[i];
        if (pid != -1) {
            children_by_id[pid].push_back(posts[i].id);
        }
    }

    // Sort children by ID for consistent ordering
    for (int i = 1; i <= n; i++) {
        sort(children_by_id[i].begin(), children_by_id[i].end());
    }

    // DFS to print in order
    function<void(int, int)> dfs = [&](int node_id, int depth) {
        // Find the post with this ID
        int idx = -1;
        for (int i = 0; i < n; i++) {
            if (posts[i].id == node_id) {
                idx = i;
                break;
            }
        }

        // Print indentation
        for (int i = 0; i < depth; i++) {
            cout << '.';
        }
        cout << posts[idx].message << '\n';

        // Process children
        for (int child_id : children_by_id[node_id]) {
            dfs(child_id, depth + 1);
        }
    };

    // Start from root (ID = 1)
    dfs(1, 0);

    return 0;
}

